INSERT OR IGNORE INTO categories(name,slug,description,sort_order) VALUES ('Star Wars News','star-wars-news','Franchise news, reviews, announcements and sourced media coverage.',26);
CREATE TABLE IF NOT EXISTS star_wars_news_cleanup_map (duplicate_id INTEGER PRIMARY KEY,keeper_id INTEGER NOT NULL);
INSERT OR IGNORE INTO star_wars_news_cleanup_map(duplicate_id,keeper_id)
SELECT t.id, (SELECT MIN(k.id) FROM threads k WHERE k.user_id=t.user_id AND k.body=t.body AND k.deleted_at IS NULL AND k.category_id=t.category_id)
FROM threads t JOIN categories c ON c.id=t.category_id WHERE c.slug='star-wars' AND t.user_id=210 AND t.deleted_at IS NULL AND instr(t.body,'News from Star Wars News Net.')=1 AND instr(t.body,'Read the original article: https://www.starwarsnewsnet.com/')>0 AND EXISTS(SELECT 1 FROM threads k WHERE k.id<t.id AND k.user_id=t.user_id AND k.body=t.body AND k.category_id=t.category_id AND k.deleted_at IS NULL);
UPDATE posts SET thread_id=(SELECT keeper_id FROM star_wars_news_cleanup_map WHERE duplicate_id=posts.thread_id) WHERE thread_id IN (SELECT duplicate_id FROM star_wars_news_cleanup_map);
UPDATE threads SET deleted_at=CURRENT_TIMESTAMP WHERE id IN (SELECT duplicate_id FROM star_wars_news_cleanup_map) AND deleted_at IS NULL;
UPDATE threads SET category_id=(SELECT id FROM categories WHERE slug='star-wars-news'),title=replace(replace(replace(replace(replace(title,'&#8217;','’'),'&#8216;','‘'),'&#8211;','–'),'&#8220;','“'),'&#8221;','”'),body='AI Bot · Automated news curator'||char(10)||char(10)||body WHERE category_id=(SELECT id FROM categories WHERE slug='star-wars') AND user_id=210 AND deleted_at IS NULL AND instr(body,'News from Star Wars News Net.')=1 AND instr(body,'Read the original article: https://www.starwarsnewsnet.com/')>0;
